-- ----------------------------
-- Table structure for psy_follow_up
-- ----------------------------
DROP TABLE IF EXISTS `psy_follow_up`;
CREATE TABLE `psy_follow_up`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '随访ID',
  `user_id` bigint(20) NOT NULL COMMENT '学生ID',
  `record_id` bigint(20) NULL DEFAULT NULL COMMENT '关联测评记录ID',
  `doctor_id` bigint(20) NULL DEFAULT NULL COMMENT '负责心理教师ID',
  `follow_date` date NOT NULL COMMENT '随访日期',
  `follow_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '线上' COMMENT '随访方式',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '待随访' COMMENT '随访状态',
  `symptom_score` int(11) NULL DEFAULT NULL COMMENT '状态自评(0-10)',
  `doctor_note` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '心理教师随访记录',
  `next_follow_date` date NULL DEFAULT NULL COMMENT '下次随访日期',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生心理随访表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of psy_follow_up
-- ----------------------------

-- ----------------------------
-- Table structure for psy_knowledge
-- ----------------------------
DROP TABLE IF EXISTS `psy_knowledge`;
CREATE TABLE `psy_knowledge`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文章标题',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '心理科普' COMMENT '文章分类',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文章摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章正文',
  `author` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '系统知识库' COMMENT '作者',
  `view_count` int(11) NULL DEFAULT 0 COMMENT '阅读量',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态(0停用 1启用)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_knowledge_category`(`category` ASC) USING BTREE,
  INDEX `idx_knowledge_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '心理知识库表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of psy_knowledge
-- ----------------------------

-- ----------------------------
-- Table structure for psy_message
-- ----------------------------
DROP TABLE IF EXISTS `psy_message`;
CREATE TABLE `psy_message`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '接收用户ID（null为全员）',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '消息内容',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'system' COMMENT '消息类型（system/follow/result）',
  `is_read` int(1) NULL DEFAULT 0 COMMENT '是否已读（0未读 1已读）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '消息通知表' ROW_FORMAT = DYNAMIC;

